function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 50) return 'nums needs 2 to 50 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 100)) return 'Each value is an integer from 0 to 100.';
  const largest = Math.max(...nums);
  if (nums.filter(v => v === largest).length !== 1) return 'The largest value must appear only once.';
  return null;
}

