function generate(rand, size) {
  const n = size === 'large' ? 50 : 2 + Math.floor(rand() * 7);
  const top = size === 'large' ? 100 : 20;
  for (;;) {
    const dominant = rand() < 0.5;
    const limit = dominant ? Math.floor(top / 2) : top;
    const nums = Array.from({ length: n }, () => Math.floor(rand() * (limit + 1)));
    if (dominant) {
      const rest = Math.max(...nums);
      const at = Math.floor(rand() * n);
      nums[at] = Math.min(top, 2 * rest + Math.floor(rand() * 3));
    }
    const largest = Math.max(...nums);
    if (nums.filter(v => v === largest).length === 1) return [nums];
  }
}
